imp = lambda a, b: (not a) or b
def valid(f, n):
    D = range(n)
    for P in itertools.product([0, 1], repeat=n):
        for Q in itertools.product([0, 1], repeat=n):
            for Rb in itertools.product([0, 1], repeat=n*n):
                R = lambda x, y: Rb[x*n + y]
                if not f(D, P, Q, R):
                    return (False, n, P, Q, Rb)
    return (True,)
