import itertools
edges = [('W', 'T'), ('W', 'V'), ('T', 'A'), ('V', 'A'), ('A', 'D')]
nodes = 'WTVAD'
par = {n: [a for a, b in edges if b == n] for n in nodes}
def ancestors(S):
    out = set(S); changed = True
    while changed:
        changed = False
        for n in list(out):
            for p in par[n]:
                if p not in out:
                    out.add(p); changed = True
    return out
def d_separated(x, y, Z):
    keep = ancestors({x, y} | set(Z))                      # ancestral graph, then moralise
    adj = {n: set() for n in keep}
    for n in keep:
        ps = [p for p in par[n] if p in keep]
        for p in ps:
            adj[n].add(p); adj[p].add(n)
        for p, q in itertools.combinations(ps, 2):
            adj[p].add(q); adj[q].add(p)
    seen, stack = {x}, [x]
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if v not in Z and v not in seen:
                seen.add(v); stack.append(v)
    return y not in seen
