# numeric confirmation with random CPTs: max |P(x,y|z) - P(x|z)P(y|z)| over 200 random networks
import numpy as np
rng = np.random.default_rng(5)
idx = {n: i for i, n in enumerate(nodes)}
def joint():
    cpt = {n: rng.uniform(0.05, 0.95, size=(2,) * len(par[n])) for n in nodes}
    J = np.zeros((2,) * 5)
    for s in itertools.product([0, 1], repeat=5):
        pr = 1.0
        for n in nodes:
            p1 = cpt[n][tuple(s[idx[q]] for q in par[n])] if par[n] else cpt[n]
            pr *= p1 if s[idx[n]] else 1 - p1
        J[s] = pr
    return J
def gap(J, x, y, Z):
    others = tuple(i for i in range(5) if i not in {idx[x], idx[y]} | {idx[z] for z in Z})
    P = J.sum(axis=others)                                  # over x, y, Z (axes in original order)
    order = [idx[x], idx[y]] + [idx[z] for z in Z]
    keep = sorted(order); P = np.transpose(P, [keep.index(o) for o in order])
    Pz = P.sum(axis=(0, 1)); Px = P.sum(axis=1); Py = P.sum(axis=0)
    return float(np.abs(P / Pz - (Px / Pz)[:, None] * (Py / Pz)[None, :]).max())
tests = {'A': ('T', 'V', []), 'B': ('T', 'V', ['W']), 'C': ('T', 'V', ['W', 'D']), 'D': ('W', 'D', ['T'])}
