print('min gap  ', {k: round(v, 6) for k, v in best.items()})

import itertools
F = [('B', 'A'), ('A', 'C'), ('B', 'D'), ('C', 'E')]
def closure(X):
    X = set(X); changed = True
    while changed:
        changed = False
        for l, r in F:
            if set(l) <= X and not set(r) <= X:
                X |= set(r); changed = True
    return X
def bcnf_violations(R):
    R = set(R); bad = []
    for k in range(1, len(R) + 1):
        for X in itertools.combinations(sorted(R), k):
            c = closure(X) & R                             # dependencies X -> Y implied by F with X, Y inside R
            if c > set(X) and c != R:                      # non-trivial and X is not a superkey of R
                bad.append((''.join(X), ''.join(sorted(c - set(X)))))
    return bad
